    public async Task InvokeAsync(HttpContext context)
    {
        // 1️⃣ Read the incoming header or create a new GUID
        var correlationId = context.Request.Headers["X-Correlation-ID"].FirstOrDefault();
        if (string.IsNullOrWhiteSpace(correlationId))
        {
            correlationId = Guid.NewGuid().ToString();
        }

        // 2️⃣ Store it in HttpContext.Items for later components
        context.Items[CorrelationKey] = correlationId;

        // 3️⃣ Add the header to the response (will be sent after the pipeline runs)
        context.Response.OnStarting(() =>
        {
            context.Response.Headers["X-Correlation-ID"] = correlationId;
            return Task.CompletedTask;
        });

        // 4️⃣ Continue to the next middleware
        await _next(context);
    }

    // Helper for other code to read the value
    public static string? GetCorrelationId(HttpContext context) =>
        context.Items.TryGetValue(CorrelationKey, out var value) ? value as string : null;
}

