using System;
using System.Threading.Tasks;
using Microsoft.Extensions.Primitives;

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

app.Use(async (context, next) =>
{
    const string headerName = "X-Correlation-ID";
    string correlationId;
    if (context.Request.Headers.TryGetValue(headerName, out var values) && !StringValues.IsNullOrEmpty(values))
    {
        correlationId = values[0];
    }
    else
    {
        correlationId = Guid.NewGuid().ToString();
    }

    // Store in HttpContext.Items
    context.Items[headerName] = correlationId;

    // Ensure the response header is set just before the response is sent
    context.Response.OnStarting(() =>
    {
        context.Response.Headers[headerName] = correlationId;
        return Task.CompletedTask;
    });

    await next();
});

app.MapGet("/", (HttpContext ctx) =>
{
    var correlationId = ctx.Items["X-Correlation-ID"]?.ToString() ?? "none";
    return Results.Ok(new { Message = "Hello", CorrelationId = correlationId });
});

app.Run();

