{
    var id = Interlocked.Increment(ref nextId);
    var todo = new Todo { Id = id, Title = dto.Title, IsDone = false };
    todos[id] = todo;
    return Results.Created($"/todos/{id}", todo);
});

// PUT /todos/{id}
app.MapPut("/todos/{id:int}", (int id, TodoUpdateDto dto) =>
{
    if (!todos.TryGetValue(id, out var todo))
        return Results.NotFound();

    todo.Title = dto.Title;
    todo.IsDone = dto.IsDone;
    return Results.NoContent();
});

// DELETE /todos/{id}
app.MapDelete("/todos/{id:int}", (int id) =>
{
    return todos.TryRemove(id, out _)
        ? Results.NoContent()
        : Results.NotFound();
});

app.Run();

