```csharp
// Program.cs
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Routing;
using System.Collections.Concurrent;

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

// In-memory store
var todos = new ConcurrentDictionary<int, Todo>();
var nextId = 1;

app.MapGet("/todos", () => todos.Values);

app.MapGet("/todos/{id:int}", (int id) =>
{
    return todos.TryGetValue(id, out var todo) ? Results.Ok(todo) : Results.NotFound();
});

app.MapPost("/todos", async (TodoCreate create) =>
{
    var id = Interlocked.Increment(ref nextId) - 1;
    var todo = new Todo(id, create.Title, create.IsCompleted);
    todos[id] = todo;
    return Results.Created($"/todos/{id}", todo);
});

app.MapPut("/todos/{id:int}", (int id, TodoUpdate update) =>
{
    if (!todos.ContainsKey(id))
        return Results.NotFound();
    var updated = new Todo(id, update.Title, update.IsCompleted);
    todos[id] = updated;
    return Results.NoContent();
});

app.MapDelete("/todos/{id:int}", (int id) =>
{
    return todos.TryRemove(id, out _) ? Results.NoContent() : Results.NotFound();
});

app.Run();

record Todo(int Id, string Title, bool IsCompleted);
record TodoCreate(string Title, bool IsCompleted);
record TodoUpdate(string Title, bool IsCompleted);

```

