// Add CORS policy that allows only https://example.com
builder.Services.AddCors(options =>
{
    options.AddPolicy("OnlyExampleCom", policy =>
    {
        policy.WithOrigins("https://example.com")
              .AllowAnyHeader()
              .AllowAnyMethod();
    });
});

var app = builder.Build();

// Apply the CORS policy globally before routing
app.UseCors("OnlyExampleCom");

// GET /api/data endpoint
app.MapGet("/api/data", () => Results.Ok(new { Message = "Hello from the API" }));

app.Run();

